compile.workshop:
variables {
    global:
        0: g
        1: h
        2: A
}

//Optimizations disabled
rule ("true if") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(1, ==, 1));
            Set Global Variable(g, 1);
        End;
    }
}

rule ("false if") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Add(1, 1), ==, 3));
            Set Global Variable(g, 4);
        End;
    }
}

rule ("true if else") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(1, ==, 1));
            Set Global Variable(g, 1);
        Else;
            Set Global Variable(g, 2);
        End;
    }
}

rule ("false if else") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(1, ==, 2));
            Set Global Variable(g, 1);
        Else;
            Set Global Variable(g, 2);
        End;
    }
}

rule ("false elif") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.A, ==, 1));
            Set Global Variable(g, 1);
        Else If(Compare(1, ==, 2));
            Set Global Variable(g, 2);
        Else;
            Set Global Variable(g, 3);
        End;
    }
}

rule ("false while") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(1, ==, 2));
            Set Global Variable(g, 1);
            Wait(1, Ignore Condition);
        End;
    }
}

